/// Receiver wake callback copied by a successful owning call.
///
/// See `mln_wake` in the
/// [C API reference](https://maplibre.org/maplibre-native-ffi/reference/c/wake_8h.html).
pub const Wake = struct {
    context: ?*anyopaque = null,
    release_context: ?*const fn (?*anyopaque) void = null,
    callback: ?*const fn (?*anyopaque) status.Error!void = null,
    pub fn toNative(self: Wake, allocator: std.mem.Allocator, roots: *callback.Roots) status.Error!c.mln_wake {
        _ = allocator;
        var raw = std.mem.zeroes(c.mln_wake);
        raw.size = @sizeOf(c.mln_wake);
        raw.callback = if (self.callback != null) callbackTrampoline else null;
        if (!(self.callback == null)) {
            const retained = try roots.retain(Wake, self);
            raw.user_data = retained;
            raw.release_user_data = callback.Registration(Wake).releaseNative;
        }
        return raw;
    }
    fn callbackTrampoline(native_arg_0: marshal.CallbackArg(c.mln_wake_callback, 0)) callconv(.c) marshal.CallbackResult(c.mln_wake_callback) {
        return struct {
            fn invoke(callback_arg_0: marshal.CallbackArg(c.mln_wake_callback, 0)) status.Error!marshal.CallbackResult(c.mln_wake_callback) {
                const state = callback.Registration(Wake).get(callback_arg_0);
                const host = state.value.callback orelse {
                    return;
                };
                host(state.value.context) catch return;
            }
        }.invoke(native_arg_0) catch {
            return;
        };
    }
};

